/* Small dependency-free PDF exporter, TEST documents only; Windows-1252 fonts. */
(function(root){'use strict';
const safe=s=>String(s??'').replace(/[\u202f\u00a0]/g,' ');
function hex(s){let out='';for(const c of safe(s)){const n=c==='€'?128:c==='œ'?156:c==='Œ'?140:c==='–'||c==='—'?45:c==='’'||c==='‘'?39:c==='“'||c==='”'?34:c.charCodeAt(0);out+=(n<=255?n:63).toString(16).padStart(2,'0');}return out;}
const money=n=>Number(n).toFixed(2)+' EUR';
function pdfLines(d){const r=d.result,v=d.variables,p=d.person,c=d.employer;let a=['MA PAYE.0 - BULLETIN DE TEST',`Periode : ${d.period} | Cree le : ${d.createdAt}`,`Paiement : ${d.paymentDate?d.paymentDate.split('-').reverse().join('/'):'Non enregistre dans ce bulletin anterieur'}`,`Employeur : ${c.name}`,`Adresse : ${c.address||'Non renseignee'} | SIRET : ${c.siret||'Non renseigne'}`,`Salarie : ${p.name} | Poste : ${p.job}`,`Contrat : ${p.contract} | Dispositif : ${p.scheme||'Aucun'}`,`Convention : ${typeof Conventions!=='undefined'?(Conventions.display(p.idcc||c.idcc)||'A definir'):(p.idcc||c.idcc||'A definir')} | Classification : ${p.classification||'A definir'}`,''];
function row(label,qty,rate,sal,pat){a.push([safe(label).slice(0,43).padEnd(44),safe(qty).slice(0,12).padEnd(13),safe(rate).slice(0,17).padEnd(18),safe(sal).padStart(12),safe(pat).padStart(12)].join(''));}
row('RUBRIQUE','BASE / QTE','TAUX / COEFF','MONTANT','EMPLOYEUR');a.push('-'.repeat(99));row('Salaire de base test','','',money(r.base),'');for(const h of r.hours)if(Number(h.hours))row(h.label,h.hours+' h',h.rate+' x '+h.multiplier,money(h.amount),'');if(r.bonus)row('Autres primes brutes','','',money(r.bonus),'');if(r.extraGross)row('Primes / maintien supplementaires','','',money(r.extraGross),'');if(r.absence)row('Retenue absence - montant manuel','','',money(-r.absence),'');if(r.mealTaxable)row('Paniers : fraction soumise','','',money(r.mealTaxable),'');if(r.travelTaxable)row('Deplacements : fraction soumise','','',money(r.travelTaxable),'');if(r.advantages)row('Avantage en nature au brut','','',money(r.advantages),'');row('TOTAL BRUT TEST','','',money(r.gross),'');a.push('');for(const x of r.rows)row(x.label,money(x.base),x.employeeRate+'% / '+x.employerRate+'%',money(x.employee),money(x.employer));row('TOTAL COTISATIONS SAISIES','','',money(r.employee),money(r.employer));a.push('');row('Frais non soumis saisis','','',money(r.reimburse),'');if(r.advantages)row('Avantage en nature deduit du net','','',money(-r.advantages),'');if(r.advance)row('Acompte deja verse','','',money(-r.advance),'');if(r.other)row('Autres retenues nettes','','',money(-r.other),'');a.push('');row('NET AVANT PAS - TEST','','',money(r.netBefore),'');row('NET IMPOSABLE FOURNI MANUELLEMENT','','',money(r.taxable),'');row('NET SOCIAL FOURNI MANUELLEMENT','','',r.social===null?'Non renseigne':money(r.social),'');row('PRELEVEMENT A LA SOURCE DE TEST','',v.pasRate+' %',money(r.pas),'');row('NET A PAYER - SIMULATION','','',money(r.net),'');a.push('','Calculs non valides reglementairement. Aucun bulletin definitif ni DSN emis.','Taux, assiettes, net fiscal et net social fournis pour le test.','Cumuls annuels, plafonds, reductions et minima reglementaires non calcules.',`Moteur : ${d.engine}`,`Reference : ${d.id}`);if(d.issues.length)a.push('Points a verifier :',...d.issues);return a.flatMap(line=>{let result=[];let text=safe(line);while(text.length>105){let cut=text.lastIndexOf(' ',105);if(cut<30)cut=105;result.push(text.slice(0,cut));text=text.slice(cut).trimStart();}result.push(text);return result;});}
function build(d){const lines=pdfLines(d),pages=[];for(let i=0;i<lines.length;i+=47)pages.push(lines.slice(i,i+47));let objects=[null,'<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>'];const kids=[];pages.forEach((ls,i)=>{const pageId=objects.length,contentId=pageId+1;kids.push(pageId+' 0 R');let stream=`BT /F1 10 Tf 36 805 Td <${hex('TEST - NON UTILISABLE POUR UNE PAIE REELLE')}> Tj ET\nBT /F1 8 Tf 36 778 Td 14 TL\n`+ls.map((l,j)=>(j?'T* ':'')+'<'+hex(l)+'> Tj').join('\n')+`\nET\nBT /F1 9 Tf 36 35 Td <${hex('TEST - NE PAS REMETTRE A UN SALARIE | Page '+(i+1)+' / '+pages.length)}> Tj ET\n`;objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentId} 0 R >>`,`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);});objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${pages.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];objects.slice(1).forEach((o,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+o+'\nendobj\n';});const start=pdf.length;pdf+='xref\n0 '+objects.length+'\n0000000000 65535 f \n'+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;return pdf;}
const api={build};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.PayrollPDF=api;
})(typeof globalThis!=='undefined'?globalThis:this);
